#include "volk.h"
#include "fossilize.hpp"
#include "fossilize_feature_filter.hpp"
#include "replay_warnings.hpp"
#include <cstring>
#include <cstdio>
using namespace Fossilize;
int main()
{
 FeatureFilter f;
 VkPhysicalDeviceFeatures2 features={VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FEATURES_2};
 VkPhysicalDeviceProperties2 props={VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2};
 if(!f.init(VK_API_VERSION_1_2,nullptr,0,&features,&props)) return 2;
 VkRenderPassCreateInfo p={VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO};
 VkAttachmentDescription a={}; a.flags=0x80000000u;
 p.attachmentCount=1;p.pAttachments=&a;
 SupportDetail first,second;
 bool one=f.render_pass_is_supported(&p,first);
 VkSubpassDescription s={};s.flags=0x80000000u;
 p.attachmentCount=0;p.pAttachments=nullptr;p.subpassCount=1;p.pSubpasses=&s;
 bool two=f.render_pass_is_supported(&p,second);
 ReplayWarnings w;
 w.observe(ReplayFailure::Unsupported,RESOURCE_RENDER_PASS,0x100,first,{});
 w.observe(ReplayFailure::Unsupported,RESOURCE_RENDER_PASS,0x200,second,{});
 auto snapshot=w.snapshot();
 printf("attachment_supported=%d subpass_supported=%d first=%s required=%llu available=%llu second=%s required=%llu available=%llu groups=%u observations=%llu\n",one,two,first.identifier,(unsigned long long)first.required,(unsigned long long)first.available,second.identifier,(unsigned long long)second.required,(unsigned long long)second.available,snapshot.count,(unsigned long long)snapshot.groups[0].count);
 w.finish(0,0,[](const char*line){puts(line);});
 if(one||two||first.kind!=SupportKind::Constraint||second.kind!=SupportKind::Constraint) return 2;
 if(snapshot.count!=2){fputs("FAIL independent/M19-distinct-render-pass-predicate-context\n",stderr);return 1;}
 return 0;
}

